using InventoryWarehouseApi.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace InventoryWarehouseApi.Infrastructure.Persistence.Configurations;
internal sealed class LowStockAlertConfiguration:IEntityTypeConfiguration<LowStockAlert>{public void Configure(EntityTypeBuilder<LowStockAlert>b){b.ToTable("LowStockAlerts",t=>{t.HasCheckConstraint("CK_LowStockAlerts_ThresholdQuantity_NonNegative","[ThresholdQuantity] >= 0");t.HasCheckConstraint("CK_LowStockAlerts_AvailableQuantity_NonNegative","[AvailableQuantity] >= 0");t.HasCheckConstraint("CK_LowStockAlerts_ObservationTimestamp","[LastObservedAtUtc] >= [TriggeredAtUtc]");t.HasCheckConstraint("CK_LowStockAlerts_ResolutionTimestamp","[ResolvedAtUtc] IS NULL OR [ResolvedAtUtc] >= [TriggeredAtUtc]");});b.HasKey(x=>x.Id);b.Ignore(x=>x.IsActive);b.Property(x=>x.ThresholdQuantity).HasPrecision(18,3);b.Property(x=>x.AvailableQuantity).HasPrecision(18,3);b.HasOne<LowStockThreshold>().WithMany().HasForeignKey(x=>x.LowStockThresholdId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.TriggeredAtUtc,x.Id}).IsDescending(true,true);b.HasIndex(x=>x.LowStockThresholdId);b.HasIndex(x=>x.LowStockThresholdId).IsUnique().HasFilter("[ResolvedAtUtc] IS NULL").HasDatabaseName("UX_LowStockAlerts_ActiveThreshold");}}
